python3 -c 'import os, re, sys
root = os.path.join(sys.argv[1], "..", "references")
index = open(os.path.join(root, "README.md"), encoding="utf-8").read()
rows = [l for l in index.splitlines() if l.startswith("| ") and l.count("|") >= 6 and not l.startswith("| Folder")]
named, problems, folder = set(), [], ""
for row in rows:
    cells = [c.strip() for c in row.strip("|").split("|")]
    if cells[0]:
        folder = cells[0].strip("`").rstrip("/")
    docs = re.findall(r"`([^`]+\.md|[^`]+/)`", cells[1])
    for doc in docs:
        path = os.path.join(root, folder, doc)
        named.add(os.path.normpath(path))
        if cells[3] == "present" and not os.path.exists(path):
            problems.append("marked present but missing: " + folder + "/" + doc)
    if cells[3] == "present" and not cells[4].strip("—- "):
        problems.append("present without an Orkeon version: " + cells[1])
version = re.compile(r"main`? at [0-9a-f]{7}|\d+\.\d+\.\d+(-[0-9A-Za-z.]+)?")
for base, dirs, files in os.walk(root):
    dirs[:] = [x for x in dirs if x != "local"]
    for f in files:
        if not f.endswith(".md") or f == "README.md":
            continue
        path = os.path.normpath(os.path.join(base, f))
        if path not in named and os.path.normpath(base) not in named:
            problems.append("not in references/README.md: " + os.path.relpath(path, root))
        head = " ".join(open(path, encoding="utf-8").read().splitlines()[:12])
        if not version.search(head):
            problems.append("states no Orkeon version in its header: " + os.path.relpath(path, root))
print("\n".join(problems) if problems else "ok %d documents" % len(named))
sys.exit(1 if problems else 0)' {{CLAUDE}}

